import React, { useEffect, useState } from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMapEvents, Polyline } from 'react-leaflet';
import L from 'leaflet';
import VehicleIcon from './VehicleIcon';
import StationIcon from './StationIcon';
import { getTrafficData } from '../services/trafficService';

const MapClickHandler = ({ onMapClick }) => {
  useMapEvents({
    click: (e) => {
      if (e && e.latlng) {
        const { lat, lng } = e.latlng;
        onMapClick({ lat, lng });
      } else {
        console.error("LatLng is undefined", e);
      }
    },
  });
  return null;
};

const getOffset = (index) => {
  const offset = 0.0005; // Adjust this value for better spacing
  return {
    lat: (index % 10) * offset,
    lng: Math.floor(index / 10) * offset
  };
};

const getColorForTraffic = (jamFactor) => {
  if (jamFactor < 4) return 'green';
  if (jamFactor < 8) return 'yellow';
  return 'red';
};

const MapComponent = React.memo(({ vehicles, stations, onMapClick }) => {
  const [trafficData, setTrafficData] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
      const bounds = L.latLngBounds(L.latLng(-37.814, 144.96332), L.latLng(-37.814, 144.96332)); // Adjust bounds as needed
      const data = await getTrafficData(bounds);
      if (data && data.RWS) {
        const trafficSegments = data.RWS.flatMap(roadwaySegment =>
          roadwaySegment.RW.flatMap(roadway =>
            roadway.FIS.flatMap(flowItemSet =>
              flowItemSet.FI.map(flowItem => ({
                coordinates: flowItem.SHP[0].split(' ').map(coord => {
                  const [lat, lon] = coord.split(',');
                  return [parseFloat(lat), parseFloat(lon)];
                }),
                color: getColorForTraffic(flowItem.CF[0].JF)
              }))
            )
          )
        );
        setTrafficData(trafficSegments);
      }
    };
    fetchData();
  }, []);

  return (
    <MapContainer center={[-37.814, 144.96332]} zoom={13} style={{ height: '100%', width: '100%' }}>
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution="&copy; <a href='https://www.openstreetmap.org/copyright'>OpenStreetMap</a> contributors"
      />
      <MapClickHandler onMapClick={onMapClick} />
      {vehicles.map((vehicle, index) => {
        const offset = getOffset(index);
        const position = [vehicle.location.lat + offset.lat, vehicle.location.lng + offset.lng];
        return (
          <Marker key={vehicle.id} position={position} icon={VehicleIcon}>
            <Popup>
              <div>
                <h3>{vehicle.name}</h3>
                <p>Capacity: {vehicle.battery_capacity}</p>
                <p>Battery: {vehicle.battery}</p>
                <p>Consumption: {vehicle.consumption}</p>
              </div>
            </Popup>
          </Marker>
        );
      })}
      {stations.map((station, index) => {
        const offset = getOffset(index + vehicles.length);
        const position = [station.location.lat + offset.lat, station.location.lng + offset.lng];
        return (
          <Marker key={station.id} position={position} icon={StationIcon}>
            <Popup>
              <div>
                <h3>{station.name}</h3>
                <p>Price per kwh: {station.price_per_kwh}</p>
                <p>Charging speed: {station.charging_speed}</p>
                <p>Buy price per kwh: {station.buy_price_per_kwh}</p>
                <p>Discharging speed: {station.discharging_speed}</p>
              </div>
            </Popup>
          </Marker>
        );
      })}
      {trafficData.map((segment, index) => (
        <Polyline key={index} positions={segment.coordinates} color={segment.color} weight={5} />
      ))}
    </MapContainer>
  );
});

export default MapComponent;
